insert into public.chai_posts (kind,title,intro,cover_color,content,status,publish_at,ends_at) values
('poll','What do you break your fast with first?',null,'saffron','{"options": [{"id": "o1", "label": "Dates and water"}, {"id": "o2", "label": "Samosa, no question"}, {"id": "o3", "label": "Fruit chaat"}, {"id": "o4", "label": "Straight to the main plate"}]}'::jsonb,'live',now() - interval '0 hours',now() + interval '7 days'),
('poll','How early do you get to Eid prayer?',null,'rose','{"options": [{"id": "o1", "label": "Early, for a parking spot"}, {"id": "o2", "label": "Right on time"}, {"id": "o3", "label": "Running in during the takbeer"}, {"id": "o4", "label": "I''m on the setup crew"}]}'::jsonb,'live',now() - interval '1 hours',now() + interval '10 days'),
('poll','Which day of Eid is the best day?',null,'cardamom','{"options": [{"id": "o1", "label": "Day 1, obviously"}, {"id": "o2", "label": "Day 2, the leftovers"}, {"id": "o3", "label": "Day 3, the rest day"}]}'::jsonb,'live',now() - interval '2 hours',now() + interval '14 days'),
('personality','Which Ramadan snack are you?','Six quick questions. No wrong answers, only delicious ones.','masala','{"results": [{"id": "date", "name": "The date", "description": "Reliable, sweet and the reason everyone gets started. People count on you, and you never make a fuss about it."}, {"id": "samosa", "name": "The samosa", "description": "Warm, a little extra, and somehow at every gathering. People say they''ll have just one when you''re around. It''s never just one."}, {"id": "roohafza", "name": "The Rooh Afza", "description": "Bright, nostalgic and the life of the iftar. You bring the energy and everyone remembers when you showed up."}, {"id": "chaat", "name": "The fruit chaat", "description": "Colorful, balanced and secretly the healthy one. You keep the table fresh and the conversation lively."}], "questions": [{"id": "q1", "text": "What''s your iftar energy?", "answers": [{"id": "a", "text": "Calm and ready, table set early", "result": "date"}, {"id": "b", "text": "In the kitchen until the last second", "result": "samosa"}, {"id": "c", "text": "Hosting the whole family, music on", "result": "roohafza"}, {"id": "d", "text": "Making sure there''s something healthy", "result": "chaat"}]}, {"id": "q2", "text": "Pick a suhoor alarm style", "answers": [{"id": "a", "text": "One alarm, up instantly", "result": "date"}, {"id": "b", "text": "Five snoozes and a sprint", "result": "samosa"}, {"id": "c", "text": "Someone else wakes me up, loudly", "result": "roohafza"}, {"id": "d", "text": "I''m already up, smoothie in hand", "result": "chaat"}]}, {"id": "q3", "text": "It''s 20 minutes to Maghrib. Where are you?", "answers": [{"id": "a", "text": "Already at the table, plate ready", "result": "date"}, {"id": "b", "text": "In the kitchen, frying something", "result": "samosa"}, {"id": "c", "text": "Stuck in traffic with a date in my pocket", "result": "roohafza"}, {"id": "d", "text": "At the masjid for the community iftar", "result": "chaat"}]}, {"id": "q4", "text": "Your role at a community iftar", "answers": [{"id": "a", "text": "Handing out dates and water at the door", "result": "date"}, {"id": "b", "text": "Behind the serving table", "result": "samosa"}, {"id": "c", "text": "Getting everyone to sit together", "result": "roohafza"}, {"id": "d", "text": "Cleaning up before anyone asks", "result": "chaat"}]}, {"id": "q5", "text": "Pick a drink", "answers": [{"id": "a", "text": "Water. Simple.", "result": "date"}, {"id": "b", "text": "Chai, extra strong", "result": "samosa"}, {"id": "c", "text": "Anything pink and sweet", "result": "roohafza"}, {"id": "d", "text": "Fresh lemonade", "result": "chaat"}]}, {"id": "q6", "text": "Your friends would describe you as", "answers": [{"id": "a", "text": "Dependable", "result": "date"}, {"id": "b", "text": "The fun one", "result": "samosa"}, {"id": "c", "text": "Unforgettable", "result": "roohafza"}, {"id": "d", "text": "Thoughtful", "result": "chaat"}]}]}'::jsonb,'live',now() - interval '3 hours',null),
('personality','What''s your masjid parking lot personality?','Five questions about the most competitive place in town.','plum','{"results": [{"id": "early", "name": "The early bird", "description": "You''re there 30 minutes before the khutbah with the front spot and a calm heart. The parking lot volunteers know you by name."}, {"id": "walker", "name": "The far-away walker", "description": "You park three blocks out on purpose. Extra steps, zero stress, and you''re out first when it''s over."}, {"id": "carpool", "name": "The carpool captain", "description": "You bring the whole family, two uncles and a neighbor. One spot, eight people. Efficient."}, {"id": "sprinter", "name": "The last-minute sprinter", "description": "You arrive as the iqamah starts and somehow find a spot anyway. Nobody knows how. Neither do you."}], "questions": [{"id": "q1", "text": "When do you leave for Jummah?", "answers": [{"id": "a", "text": "An hour early", "result": "early"}, {"id": "b", "text": "Early enough to walk in", "result": "walker"}, {"id": "c", "text": "When everyone''s finally in the car", "result": "carpool"}, {"id": "d", "text": "When I hear the adhan on my phone", "result": "sprinter"}]}, {"id": "q2", "text": "The lot is full. You\u2026", "answers": [{"id": "a", "text": "Never find out, I''m already parked", "result": "early"}, {"id": "b", "text": "Head straight to the side street", "result": "walker"}, {"id": "c", "text": "Drop everyone at the door first", "result": "carpool"}, {"id": "d", "text": "Circle once and get lucky", "result": "sprinter"}]}, {"id": "q3", "text": "Who''s in your car?", "answers": [{"id": "a", "text": "Just me and some quiet", "result": "early"}, {"id": "b", "text": "Me and a podcast", "result": "walker"}, {"id": "c", "text": "Everyone I could fit", "result": "carpool"}, {"id": "d", "text": "Whoever was ready on time", "result": "sprinter"}]}, {"id": "q4", "text": "After the prayer you\u2026", "answers": [{"id": "a", "text": "Stay for tea and catch up", "result": "early"}, {"id": "b", "text": "Walk out and beat the traffic", "result": "walker"}, {"id": "c", "text": "Wait 20 minutes for the family to gather", "result": "carpool"}, {"id": "d", "text": "Sprint back to work", "result": "sprinter"}]}, {"id": "q5", "text": "Your parking superpower", "answers": [{"id": "a", "text": "Patience", "result": "early"}, {"id": "b", "text": "Strong legs", "result": "walker"}, {"id": "c", "text": "A minivan", "result": "carpool"}, {"id": "d", "text": "Pure luck", "result": "sprinter"}]}]}'::jsonb,'live',now() - interval '4 hours',null),
('trivia','How well do you know the Prophets'' stories?','Six questions from the stories in the Quran.','cardamom','{"questions": [{"id": "q1", "text": "Which prophet built the Ark?", "answers": [{"id": "a", "text": "Ibrahim"}, {"id": "b", "text": "Nuh"}, {"id": "c", "text": "Musa"}, {"id": "d", "text": "Isa"}], "correct": "b"}, {"id": "q2", "text": "Which prophet was swallowed by a great fish?", "answers": [{"id": "a", "text": "Yunus"}, {"id": "b", "text": "Yusuf"}, {"id": "c", "text": "Ayyub"}, {"id": "d", "text": "Dawud"}], "correct": "a"}, {"id": "q3", "text": "Which prophet is called Khalilullah, the friend of Allah?", "answers": [{"id": "a", "text": "Ismail"}, {"id": "b", "text": "Ibrahim"}, {"id": "c", "text": "Nuh"}, {"id": "d", "text": "Sulaiman"}], "correct": "b"}, {"id": "q4", "text": "Which prophet could understand the speech of birds and ants?", "answers": [{"id": "a", "text": "Dawud"}, {"id": "b", "text": "Musa"}, {"id": "c", "text": "Sulaiman"}, {"id": "d", "text": "Yahya"}], "correct": "c"}, {"id": "q5", "text": "Which prophet''s staff turned into a snake?", "answers": [{"id": "a", "text": "Musa"}, {"id": "b", "text": "Harun"}, {"id": "c", "text": "Isa"}, {"id": "d", "text": "Ibrahim"}], "correct": "a"}, {"id": "q6", "text": "Which prophet was thrown into a well by his brothers?", "answers": [{"id": "a", "text": "Yaqub"}, {"id": "b", "text": "Yusuf"}, {"id": "c", "text": "Ishaq"}, {"id": "d", "text": "Lut"}], "correct": "b"}], "tiers": [{"min": 0, "name": "Keep reading", "description": "Every story is waiting for you. Start with Surah Yusuf, it''s one of the best."}, {"min": 3, "name": "Solid foundation", "description": "You know the big moments. A few more stories and you''ll be the one telling them at family gatherings."}, {"min": 5, "name": "Storyteller", "description": "You know these stories well. The kids in your family are lucky to have you."}]}'::jsonb,'live',now() - interval '5 hours',null);
